function normalizeJourney(raw={}) { const j=freshJourney(), a=raw.assessment||{}, adv=raw.advanced||{}; j.assessment.index=Math.max(0,Math.min(9,Number(a.index)||0)); j.assessment.answers=Array.from({length:10},(_,i)=>Number.isInteger(a.answers?.[i])&&a.answers[i]>=0&&a.answers[i]<4?a.answers[i]:null); j.assessment.complete=Boolean(a.complete); j.advanced.index=Math.max(0,Math.min(4,Number(adv.index)||0)); j.advanced.complete=Boolean(adv.complete); for(const k of ["education","experience","workstyle","motivation"]) j.advanced.data[k]=adv.data?.[k]||null; j.advanced.data.skills=Array.isArray(adv.data?.skills)?[...new Set(adv.data.skills)].filter(Boolean):[]; j.selectedCareer=DATA.tracks[raw.selectedCareer]?raw.selectedCareer:"tech"; j.compare=Array.isArray(raw.compare)?raw.compare.map(k=>DATA.tracks[k]?k:"tech").slice(0,2):["tech","business"]; if(j.compare.length<2) j.compare.push("business"); j.roadmap=Array.isArray(raw.roadmap)?[...new Set(raw.roadmap)].filter(Boolean):[]; j.result=raw.result||null; return j; }
function migrateLegacy() { try { const legacy=JSON.parse(localStorage.getItem(LEGACY)); if(!legacy) return null; const j=normalizeJourney(legacy); const map={"Secondary school or equivalent":"school","Diploma or undergraduate study":"diploma","Bachelor's degree or higher":"degree","Learning independently or changing direction":"independent","I am just getting started":"starting","I have classroom or personal projects":"projects","I have internship or volunteer experience":"internship","I am ready to show work publicly":"ready","Focused and structured":"focused","Collaborative and varied":"collaborative","Active and operational":"operational","People-facing and creative":"creative","Building a practical portfolio":"portfolio","Exploring more than one path":"explore","Contributing to a growing sector":"sector","Finding a confidence-building first project":"confidence"}; for(const k of ["education","experience","workstyle","motivation"]) j.advanced.data[k]=map[j.advanced.data[k]]||j.advanced.data[k]; const skills={"Spreadsheets":"spreadsheets","Research":"research","Presentations":"presentations","Coding basics":"coding","Languages":"languages","Project planning":"planning","Design thinking":"design","Customer service":"service"}; j.advanced.data.skills=j.advanced.data.skills.map(x=>skills[x]||x); return {preferences:{locale:"en",theme:"light"},session:{activeProfileId:"guest"},profiles:{guest:{identity:{displayName:"Guest",email:"",kind:"guest"},journey:j}}}; } catch { return null; } }
function load() { try { const stored=JSON.parse(localStorage.getItem(STORE)); if(stored?.preferences&&stored?.profiles) { const base=emptyState(); const profiles={}; Object.entries(stored.profiles).forEach(([id,p])=>profiles[id]={identity:{displayName:String(p.identity?.displayName||"Guest").slice(0,60),email:String(p.identity?.email||"").slice(0,160),kind:p.identity?.kind==="guest"?"guest":"local"},journey:normalizeJourney(p.journey)}); return {...base,...stored,preferences:{...base.preferences,...stored.preferences},session:{...base.session,...stored.session},profiles}; } const legacy=migrateLegacy(); if(legacy) { try { localStorage.setItem(STORE,JSON.stringify(legacy)); localStorage.removeItem(LEGACY); } catch {} return legacy; } } catch {} return emptyState(); }
