function activeProfile(){return state.session.activeProfileId?state.profiles[state.session.activeProfileId]||null:null;} function journey(){return activeProfile()?.journey||null;}
function updateResult(j=journey()){ if(!j)return null; const scores=scoreTracks(j); j.result={scores,leadKey:scores[0].key,generatedAt:Date.now()}; return j.result; }
function scoreTracks(j=journey()){ const values=Object.fromEntries(Object.keys(DATA.tracks).map(k=>[k,52])); j?.assessment.answers.forEach((a,i)=>{if(a===null||a===undefined)return; const key=QUESTIONS[i]?.[2][a]; if(key)values[key]+=6; if(a===0)values.tech++;if(a===1)values.business++;}); if(j?.advanced.complete){const d=j.advanced.data;if(d.skills.includes("coding")||d.skills.includes("spreadsheets"))values.tech+=2;if(d.skills.includes("planning"))values.business+=2;if(d.workstyle==="operational")values.logistics+=2;if(d.motivation==="sector")values.energy+=2;}return Object.entries(values).map(([key,score])=>({key,score:Math.min(94,score)})).sort((a,b)=>b.score-a.score);}
function lead(j=journey()){const r=j?.result||updateResult(j)||{leadKey:"tech",scores:scoreTracks(j)};const first=r.scores?.find(x=>x.key===r.leadKey)||r.scores?.[0]||{key:"tech",score:52};return {...DATA.tracks[first.key],key:first.key,score:first.score};}
