function heroGate(){return `<div class="view"><div class="shell"><section class="empty-dashboard"><span class="eyebrow">${t("shell","signedOut")}</span><h1>${t("assessment","startGate")}</h1><p>${t("assessment","gateText")}</p><div class="result-actions" style="justify-content:center"><button class="button" data-open-profile>${t("shell","signIn")}</button><button class="button button-outline" data-guest>${t("shell","guest")}</button></div></section></div></div>`;}
function renderHome(){const sectors=[[en("Technology & Digital","التقنية والرقمية"),en("Data, products, and connected services","البيانات والمنتجات والخدمات المتصلة"),"technology","tech"],[en("Tourism & Hospitality","السياحة والضيافة"),en("Experiences with a Saudi sense of place","تجارب بروح سعودية مرتبطة بالمكان"),"tourism","tourism"],[en("Renewable Energy","الطاقة المتجددة"),en("Solar, wind, and sustainable systems","الشمس والرياح والأنظمة المستدامة"),"energy","energy"],[en("Logistics","اللوجستيات"),en("Connected trade, operations, and supply","التجارة والعمليات والإمداد المترابطة"),"port","logistics"],[en("Healthcare","الرعاية الصحية"),en("People-centred services and innovation","خدمات وابتكار يتمحوران حول الإنسان"),null,"heart"],[en("Finance","المالية"),en("Clear decisions and growing businesses","قرارات واضحة وأعمال نامية"),null,"finance"],[en("Culture & Creative","الثقافة والإبداع"),en("Stories, design, and shared experiences","القصص والتصميم والتجارب المشتركة"),null,"creative"],[en("Smart Cities","المدن الذكية"),en("Digital places built around people","أماكن رقمية مبنية حول الناس"),null,"city"]];const facts=TEXT.home.facts;const process=TEXT.home.process;return `<div class="view"><div class="shell"><section class="hero reveal"><div class="hero-copy"><span class="eyebrow">${t("home","eyebrow")}</span><h1>${t("home","title")}</h1><p>${t("home","subtitle")}</p><div class="hero-actions"><a class="button" href="#assessment">${t("home","begin")} <span class="dir-arrow" aria-hidden="true">↗</span></a><a class="button button-outline" href="#compare">${t("home","explore")} <span aria-hidden="true">↓</span></a></div></div><div class="hero-image-wrap">${media("hero",en("Saudi professionals reviewing digital information in a modern office","محترفون سعوديون يراجعون معلومات رقمية في مكتب حديث"),"hero-image")}<div class="hero-metric"><span class="metric-glyph" aria-hidden="true">↗</span><div><b>${n(8)} ${copy(en("sectors","قطاعات"))}</b><span>${copy(en("Explore the demo paths","استكشف المسارات التوضيحية"))}</span></div></div></div></section><div class="quick-facts reveal">${facts.map(x=>{const [a,b]=copy(x).split("|");return `<div><strong>${a}</strong><span>${b}</span></div>`}).join("")}</div><section class="section reveal"><div class="section-heading"><span class="eyebrow">${copy(en("Your path, made practical","مسارك بشكل عملي"))}</span><h2>${t("home","processTitle")}</h2><p>${t("home","processIntro")}</p></div><div class="process-grid">${process.map((x,i)=>{const [title,desc]=copy(x).split("|");return `<a class="process-card" href="#${["assessment","analysis","skills","roadmap"][i]}"><span class="step-num">0${i+1}</span><strong>${title}</strong><p>${desc}</p></a>`}).join("")}</div></section><section class="section" id="sectors"><div class="section-heading reveal"><span class="eyebrow">${copy(en("Opportunity landscape","مشهد الفرص"))}</span><h2>${t("home","sectorTitle")}</h2><p>${t("home","sectorIntro")}</p></div><div class="sector-grid">${sectors.map(([title,desc,photo,type],i)=>photo?`<a class="sector-card has-image reveal" href="#compare" data-career="${type}">${media(photo,title)}<span class="sector-index">0${i+1}</span><div><h3>${copy(title)}</h3><p>${copy(desc)}</p></div></a>`:`<a class="sector-card reveal" href="#compare"><span class="sector-icon">${icon(type)}</span><div><h3>${copy(title)}</h3><p>${copy(desc)}</p></div><span class="sector-index">0${i+1}</span></a>`).join("")}</div></section><section class="section context-panel reveal"><div class="context-content"><span class="eyebrow">${copy(en("Rooted in context","متجذر في السياق"))}</span><h2>${t("home","contextTitle")}</h2><p>${t("home","contextText")}</p><ul class="check-list">${[en("Keep your own priorities at the centre.","اجعل أولوياتك في المركز."),en("Use results as prompts to investigate, not predictions.","استخدم النتائج كمحفزات للاستكشاف لا كتنبؤات."),en("Build evidence of what you can do through small projects.","ابنِ دليلاً على ما تستطيع فعله عبر مشاريع صغيرة.")].map(x=>`<li>${copy(x)}</li>`).join("")}</ul></div><div class="context-media">${media("workplace",en("Saudi professionals working together at laptops in a contemporary office","محترفون سعوديون يعملون معاً على حواسيب محمولة في مكتب معاصر"))}</div></section><section class="section cta-banner reveal"><div><span class="eyebrow">${copy(en("A starting point, not a label","نقطة بداية لا تصنيف"))}</span><h2>${t("home","finalTitle")}</h2><p>${t("home","finalText")}</p></div><a class="button" href="#assessment">${t("home","begin")} <span class="dir-arrow" aria-hidden="true">↗</span></a></section></div></div>`;}
function renderAssessment(){if(!journey())return heroGate();const j=journey(),i=j.assessment.index,[q,answers]=QUESTIONS[i],selected=j.assessment.answers[i];return `<div class="view"><div class="assessment-wrap"><div class="assessment-header"><div><span class="eyebrow">${t("shell","assessment")}</span><h1>${t("assessment","title")}</h1></div><span class="progress-copy">${t("assessment","progress",{n:n(i+1)})}</span></div><div class="progress-track" role="progressbar" aria-valuemin="1" aria-valuemax="10" aria-valuenow="${i+1}" aria-label="${t("assessment","progress",{n:n(i+1)})}"><span style="width:${(i+1)*10}%"></span></div><section class="question-card" aria-labelledby="question-title"><span class="eyebrow">${t("assessment","prompt")}</span><h2 id="question-title" tabindex="-1">${copy(q)}</h2><div class="answer-grid">${answers.map((x,a)=>`<button class="answer-card ${selected===a?"is-selected":""}" type="button" data-answer="${a}" aria-pressed="${selected===a}"><span class="answer-key">${"ABCD"[a]}</span><span class="answer-label">${copy(x)}</span><span class="answer-check" aria-hidden="true">✓</span></button>`).join("")}</div></section><div class="assessment-actions"><button class="button button-quiet" type="button" data-assessment-back ${i===0?"disabled":""}><span class="dir-arrow" aria-hidden="true">←</span> ${t("assessment","back")}</button><a class="button button-outline" href="#home">${t("assessment","leave")}</a></div><p class="assessment-note">${t("assessment","note")}</p></div></div>`;}
function renderAnalysis(stage=0){if(!journey())return heroGate();return `<div class="view"><section class="analysis"><div class="analysis-copy"><span class="eyebrow">${t("analysis","eyebrow")}</span><h1>${t("analysis","title")}</h1><p>${t("analysis","text")}</p><div class="analysis-stages" role="status" aria-live="polite">${TEXT.analysis.stages.map((s,i)=>`<div class="analysis-stage ${i<stage?"done":i===stage?"active":""}"><span>${i<stage?"✓":n(i+1)}</span><div>${copy(s)}</div></div>`).join("")}</div><button class="button button-outline" type="button" data-skip-analysis>${t("analysis","skip")} <span class="dir-arrow" aria-hidden="true">→</span></button><p class="demo-disclaimer">${t("analysis","note")}</p></div><div class="analysis-media">${media("hologram",en("Saudi team discussing a digital strategy display","فريق سعودي يناقش شاشة استراتيجية رقمية"))}<div class="analysis-badge">${copy(en("Building a useful conversation starter—not a verdict on your future.","نبني بداية حوار مفيدة، لا حكماً على مستقبلك."))}</div></div></section></div>`;}
function renderResults(){if(!journey())return heroGate();const j=journey(),scores=scoreTracks(j);j.result={scores,leadKey:scores[0].key,generatedAt:Date.now()};save();const c=lead(j);return `<div class="view"><div class="shell"><section class="results-top"><div class="result-intro reveal"><span class="eyebrow">${t("common","illustrative")}</span><h1>${copy(en("Your Career Discovery","استكشافك المهني"))}</h1><p>${copy(en("Your choices point most strongly toward a theme where your interests can become a practical next step.","تشير اختياراتك بقوة إلى موضوع يمكن أن تتحول فيه اهتماماتك إلى خطوة عملية تالية."))}</p><div class="leading-track"><strong>${copy(c.name)}</strong><span>${copy(c.desc)}</span><div class="strength-tags">${c.strengths.map(x=>`<span class="tag">${copy(x)}</span>`).join("")}</div></div></div><aside class="score-card reveal"><div><span class="score-label">${t("common","match",{score:n(c.score)})}</span><div class="score-number">${n(c.score)}<span>/100</span></div><div class="meter" role="progressbar" aria-label="${t("common","match",{score:n(c.score)})}" aria-valuenow="${c.score}" aria-valuemin="0" aria-valuemax="100"><span style="width:${c.score}%"></span></div></div><p>${copy(en("This is a non-scientific demo score based on your selected answers. It is for exploration only.","هذه درجة توضيحية غير علمية تعتمد على إجاباتك المختارة. وهي للاستكشاف فقط."))}</p></aside></section><section class="result-grid"><div class="result-panel reveal"><h2>${copy(en("Other themes worth exploring","موضوعات أخرى تستحق الاستكشاف"))}</h2><p>${copy(en("More than one route can be a good starting point. Compare the stories behind your top themes.","يمكن أن يكون أكثر من مسار بداية جيدة. قارن القصص وراء موضوعاتك الأعلى."))}</p><div class="track-list">${scores.slice(1,4).map(({key,score})=>`<a class="track-row" href="#compare" data-career="${key}"><strong>${copy(DATA.tracks[key].name)}</strong><span>${n(score)}/100</span><div class="meter"><span style="width:${score}%"></span></div></a>`).join("")}</div></div><div class="result-panel reveal"><h2>${copy(en("Roles to explore","أدوار للاستكشاف"))}</h2><p>${copy(en("Example roles to research further—not vacancies or hiring recommendations.","أدوار مثال للبحث والاستكشاف، وليست وظائف شاغرة أو توصيات توظيف."))}</p><div class="roles">${[[en("Data Analyst","محلل بيانات"),en("Turn evidence into accessible insight.","حوّل الأدلة إلى رؤى سهلة الفهم.")],[en("Business Analyst","محلل أعمال"),en("Clarify needs and make change practical.","وضّح الاحتياجات واجعل التغيير عملياً.")],[en("Software Developer","مطور برمجيات"),en("Build useful digital experiences and systems.","ابنِ تجارب وأنظمة رقمية مفيدة.")]].map(x=>`<div class="role"><strong>${copy(x[0])}</strong><span>${copy(x[1])}</span></div>`).join("")}</div></div></section><div class="result-actions reveal"><a class="button" href="#profile">${t("common","profile")} <span class="dir-arrow" aria-hidden="true">→</span></a><a class="button button-outline" href="#advanced">${copy(en("Add more detail","أضف تفاصيل أكثر"))}</a><a class="button button-quiet" href="#dashboard">${t("common","dashboard")}</a></div></div></div>`;}
function renderAdvanced(){if(!journey())return heroGate();const j=journey(),i=j.advanced.index,[key,title,choices]=ADVANCED[i],val=j.advanced.data[key];const body=key==="skills"?`<div class="chip-group">${choices.map(([id,label])=>`<button type="button" class="chip-button ${j.advanced.data.skills.includes(id)?"selected":""}" data-skill-chip="${id}" aria-pressed="${j.advanced.data.skills.includes(id)}">${copy(label)}</button>`).join("")}</div><p class="assessment-note">${copy(en("Select all that apply.","اختر كل ما ينطبق."))}</p>`:`<div class="option-stack">${choices.map(([id,label])=>`<button type="button" class="choice-button ${val===id?"selected":""}" data-advanced-choice="${id}" aria-pressed="${val===id}">${copy(label)}</button>`).join("")}</div>`;return `<div class="view"><section class="advanced-layout"><div class="advanced-card"><span class="eyebrow">${t("common","optional")}</span><h1>${copy(en("Add the details you want to bring.","أضف التفاصيل التي تريد تضمينها."))}</h1><p>${copy(en("Five short prompts help tailor the learning suggestions. You can skip this anytime; it does not make the result more official or predictive.","تساعد خمس أسئلة قصيرة في تخصيص اقتراحات التعلم. يمكنك التخطي في أي وقت؛ ولن يجعل ذلك النتيجة رسمية أو تنبؤية."))}</p><div class="progress-track" role="progressbar" aria-valuemin="1" aria-valuemax="5" aria-valuenow="${i+1}" aria-label="${copy(en(`Step ${i+1} of 5`,`الخطوة ${n(i+1)} من ٥`))}"><span style="width:${(i+1)*20}%"></span></div><div class="advanced-step"><span class="progress-copy">${copy(en(`Step ${i+1} of 5`,`الخطوة ${n(i+1)} من ٥`))}</span><h2>${copy(title)}</h2>${body}</div><div class="advanced-actions"><a class="text-button" href="#results">${copy(en("Skip and return to results","تخطَّ وارجع للنتائج"))}</a><div class="right-actions"><button class="button button-quiet" type="button" data-advanced-back ${i===0?"disabled":""}>${t("assessment","back")}</button><button class="button" type="button" data-advanced-next ${key!=="skills"&&!val?"disabled":""}>${i===4?t("common","save"):t("common","continue")} <span class="dir-arrow" aria-hidden="true">→</span></button></div></div></div></section></div>`;}
function renderProfile(){if(!journey())return heroGate();const c=DATA.tracks[journey().selectedCareer]||lead();return `<div class="view"><div class="shell"><section class="profile-hero reveal"><div class="profile-content"><span class="eyebrow">${copy(en("Your illustrative profile","ملفك التوضيحي"))}</span><h1>${copy(c.role)}<br><span style="color:var(--sand)">${copy(c.name)}</span></h1><p>${copy(c.desc)} ${copy(en("This profile turns your demo choices into a clearer story you can test through learning and small projects.","يحوّل هذا الملف اختياراتك التوضيحية إلى قصة أوضح يمكنك اختبارها بالتعلم والمشاريع الصغيرة."))}</p><div class="strength-tags">${c.strengths.map(x=>`<span class="tag">${copy(x)}</span>`).join("")}</div></div><div class="profile-media">${media(c.image,en(`${c.name.en} career environment`, `بيئة عمل ${c.name.ar}`))}</div></section><section class="section two-col"><article class="info-card reveal"><h2>${copy(en("Why this path is showing up","لماذا يظهر هذا المسار؟"))}</h2><p>${copy(en("Your choices suggested an interest in work that combines ","تشير اختياراتك إلى اهتمام بعمل يجمع بين "))}${copy(c.focus)}. ${copy(en("Treat that as a hypothesis to test—not a label to accept.","تعامل مع ذلك كفرضية للاختبار لا كتسمية يجب قبولها."))}</p><div class="demo-disclaimer">${copy(en("Your choices may change as you learn. This is illustrative content, not a validated career recommendation.","قد تتغير اختياراتك مع التعلم. هذا محتوى توضيحي وليس توصية مهنية موثقة."))}</div></article><article class="info-card reveal"><h2>${copy(en("A useful first proof","دليل أول مفيد"))}</h2><p><strong>${copy(c.proof)}</strong></p><ul class="bullet-list" style="margin-top:18px">${[en("Start small enough to finish in two weeks.","ابدأ بشيء صغير يكفي لإنهائه خلال أسبوعين."),en("Document the question, your process, and what changed.","وثّق السؤال وطريقتك وما الذي تغير."),en("Ask one person for specific feedback.","اطلب من شخص واحد ملاحظات محددة.")].map(x=>`<li>${copy(x)}</li>`).join("")}</ul></article></section><section class="section"><div class="section-heading reveal"><span class="eyebrow">${copy(en("Make it tangible","اجعله ملموساً"))}</span><h2>${copy(en("Choose the next lens for your direction.","اختر المنظور التالي لاتجاهك."))}</h2></div><div class="tool-links">${[[t("shell","skills"),en("See what to practise next.","شاهد ما الذي تمارسه تالياً."),"skills"],[t("shell","roadmap"),en("Turn intent into a ten-week plan.","حوّل النية إلى خطة لعشرة أسابيع."),"roadmap"],[t("shell","compare"),en("Place your top themes side by side.","ضع موضوعاتك الأعلى جنباً إلى جنب."),"compare"]].map(([a,b,r])=>`<a class="tool-link reveal" href="#${r}"><strong>${a} <span class="dir-arrow">→</span></strong><span>${copy(b)}</span></a>`).join("")}</div></section></div></div>`;}
function renderSkills(){if(!journey())return heroGate();const j=journey(),c=DATA.tracks[j.selectedCareer]||lead(j),boost=j.advanced.complete&&j.advanced.data.skills.length?4:0;return `<div class="view"><div class="shell skills-layout"><aside class="sticky-intro reveal"><span class="eyebrow" style="color:#ccebc6">${copy(en("A practical focus","تركيز عملي"))}</span><h1>${t("shell","skills")}</h1><p>${copy(en(`These are illustrative starting levels, not measurements of ability. Use them to choose a next learning action for ${c.role.en}.`,`هذه مستويات بداية توضيحية وليست قياساً للقدرة. استخدمها لاختيار إجراء تعلم تالٍ لـ ${c.role.ar}.`))}</p><a class="button button-outline" style="border-color:#cfe6cf;color:#fff" href="#roadmap">${copy(en("Build my roadmap","ابنِ خارطة طريقي"))} <span class="dir-arrow">→</span></a></aside><section class="skill-list">${c.skills.map(([id,name,current,target,action])=>{const level=Math.min(target-2,current+boost),label=copy(name);return `<article class="skill-row reveal"><div class="skill-row-top"><strong>${label}</strong><span class="gap-label">${copy(en(`Gap: ${target-level} points`,`الفجوة: ${n(target-level)} نقطة`))}</span></div><p>${copy(action)}</p><div class="skill-scale" role="progressbar" aria-label="${esc(copy(en(`${label}: current demo level ${n(level)} of target ${n(target)}`,`${label}: المستوى التوضيحي الحالي ${n(level)} من الهدف ${n(target)}`)))}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${level}" aria-valuetext="${esc(copy(en(`Current demo level ${n(level)}; target ${n(target)}`,`المستوى التوضيحي الحالي ${n(level)}؛ الهدف ${n(target)}`)))}"><span class="skill-current" style="width:${level}%"></span><i class="skill-target" aria-hidden="true" style="inset-inline-start:${target}%"></i></div><div class="skill-legend"><span>${copy(en(`Current demo level: ${level}`,`المستوى التوضيحي الحالي: ${n(level)}`))}</span><span>${copy(en(`Target: ${target}`,`الهدف: ${n(target)}`))}</span></div><a class="skill-action" href="#roadmap">${copy(en("Add this to my next steps","أضف هذا لخطواتي التالية"))} <span class="dir-arrow">→</span></a></article>`}).join("")}</section></div></div>`;}
function roadmap(c){return [[en("Start now","ابدأ الآن"),en("Weeks 1–2","الأسبوعان ١–٢"),[["question",en(`Choose a small ${c.role.en.toLowerCase()} question you want to explore.`,`اختر سؤالاً صغيراً تريد استكشافه في مجال ${c.role.ar}.`),en("45 min","٤٥ دقيقة")],["foundation",en(`Spend two focused sessions on ${c.focus.en.split(",")[0].toLowerCase()}.`,`اقض جلستين مركزتين في ${c.focus.ar.split("،")[0]}.`),en("2 hrs","ساعتان")]]],[en("Build proof","ابنِ دليلاً"),en("Weeks 3–6","الأسابيع ٣–٦"),[["project",en(`Create ${c.proof.en.toLowerCase()}.`,`أنشئ ${c.proof.ar}.`),en("4–6 hrs","٤–٦ ساعات")],["feedback",en("Share your draft with one peer, mentor, or instructor.","شارك مسودتك مع زميل أو مرشد أو مدرب."),en("30 min","٣٠ دقيقة")]]],[en("Apply & share","طبّق وشارك"),en("Weeks 7–10","الأسابيع ٧–١٠"),[["story",en("Describe the problem, process, and result in a short portfolio note.","صِف المشكلة والطريقة والنتيجة في ملاحظة مختصرة لملف الأعمال."),en("90 min","٩٠ دقيقة")],["compare",en("Compare two paths and select one new learning action.","قارن بين مسارين واختر إجراء تعلم جديداً واحداً."),en("30 min","٣٠ دقيقة")]]]];}
function renderRoadmap(){if(!journey())return heroGate();const j=journey(),c=DATA.tracks[j.selectedCareer]||lead(j),phases=roadmap(c),tasks=phases.flatMap(x=>x[2]),done=j.roadmap.length,pct=Math.round(done/tasks.length*100),next=tasks.find(x=>!j.roadmap.includes(x[0]));return `<div class="view"><div class="shell"><header class="roadmap-head"><div><span class="eyebrow">${copy(en("Personal demo plan","خطة تجريبية شخصية"))}</span><h1>${copy(en("Move from direction to a small, visible practice.","انتقل من الاتجاه إلى ممارسة صغيرة واضحة."))}</h1></div><div class="roadmap-progress"><b>${n(pct)}% ${t("common","complete")}</b><span>${copy(en(`${n(done)} of ${n(tasks.length)} steps marked complete`,`تم تحديد ${n(done)} من ${n(tasks.length)} خطوات كمكتملة`))}</span><div class="meter" role="progressbar" aria-label="${esc(copy(en("Roadmap progress","تقدم خارطة الطريق")))}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}" aria-valuetext="${esc(copy(en(`${n(done)} of ${n(tasks.length)} steps complete`,`${n(done)} من ${n(tasks.length)} خطوات مكتملة`)))}"><span style="width:${pct}%"></span></div></div></header><section class="next-step reveal"><span class="next-step-icon" aria-hidden="true">→</span><div><strong>${t("common","next")}</strong><span>${next?copy(next[1]):copy(en("You have completed this demo roadmap. Choose a new project to keep learning.","لقد أكملت خارطة الطريق التوضيحية. اختر مشروعاً جديداً لمواصلة التعلم."))}</span></div><a class="button button-small" href="#skills">${next?t("shell","skills"):t("shell","compare")}</a></section><section class="roadmap-phases">${phases.map(([title,time,items])=>`<article class="phase reveal"><header class="phase-header"><h2>${copy(title)}</h2><span>${copy(time)}</span></header>${items.map(([id,label,effort])=>`<div class="milestone"><input id="task-${id}" type="checkbox" data-task="${id}" ${j.roadmap.includes(id)?"checked":""}><label for="task-${id}">${copy(label)}<small>${copy(effort)} · ${t("common","demo")}</small></label></div>`).join("")}</article>`).join("")}</section><p class="demo-disclaimer">${copy(en("Roadmap actions are illustrative learning prompts. They are not qualifications, job requirements, or hiring advice.","إجراءات خارطة الطريق محفزات تعلم توضيحية. ليست مؤهلات أو متطلبات وظيفية أو نصائح توظيف."))}</p></div></div>`;}
function renderCompare(){const j=journey();if(!j)return heroGate();const[a,b]=j.compare,first=DATA.tracks[a],second=DATA.tracks[b],scores=Object.fromEntries(scoreTracks(j).map(x=>[x.key,x.score]));const select=(slot,label,cur)=>`<label class="select-field">${label}<select data-compare="${slot}">${Object.entries(DATA.tracks).map(([id,c])=>`<option value="${id}" ${id===cur?"selected":""}>${copy(c.name)}</option>`).join("")}</select></label>`;const rows=[[en("Illustrative match score","درجة تطابق توضيحية"),`${n(scores[a]||52)}/100`,`${n(scores[b]||52)}/100`],[en("Typical environment","بيئة العمل المعتادة"),copy(first.environment),copy(second.environment)],[en("Initial skill focus","تركيز المهارات الأولي"),copy(first.focus),copy(second.focus)],[en("Portfolio proof","دليل ملف الأعمال"),copy(first.proof),copy(second.proof)],[en("Suggested preparation","التحضير المقترح"),copy(first.period),copy(second.period)],[en("Related areas","مجالات مرتبطة"),copy(first.opportunities),copy(second.opportunities)]];return `<div class="view"><div class="shell"><header class="compare-header"><div><span class="eyebrow">${copy(en("Explore side by side","استكشف جنباً إلى جنب"))}</span><h1>${t("shell","compare")}</h1></div><p class="view-intro">${copy(en("Compare the work stories behind two illustrative paths, then decide what you want to investigate next.","قارن قصص العمل وراء مسارين توضيحيين ثم حدد ما تريد استكشافه تالياً."))}</p></header><div class="select-group">${select("first",copy(en("First path","المسار الأول")),a)}${select("second",copy(en("Second path","المسار الثاني")),b)}</div><section class="comparison reveal"><div class="comparison-row header"><div>${copy(en("Compare","المقارنة"))}</div><div>${copy(first.name)}</div><div>${copy(second.name)}</div></div>${rows.map(([label,x,y],i)=>`<div class="comparison-row"><div>${copy(label)}</div><div class="${i===0?"compare-score":""}">${x}</div><div class="${i===0?"compare-score":""}">${y}</div></div>`).join("")}</section><p class="comparison-note">${copy(en("All values are illustrative demo content; they do not represent labor market statistics, salaries, vacancies, or requirements.","جميع القيم محتوى توضيحي ولا تمثل إحصاءات سوق العمل أو الرواتب أو الشواغر أو المتطلبات."))}</p><div class="result-actions"><a class="button" href="#profile">${t("common","profile")} <span class="dir-arrow">→</span></a><a class="button button-outline" href="#dashboard">${t("common","dashboard")}</a></div></div></div>`;}
function renderDashboard(){const p=activeProfile();if(!p)return heroGate();const j=p.journey;if(!j.assessment.complete)return `<div class="view"><div class="shell"><section class="empty-dashboard"><span class="eyebrow">${t("shell","dashboard")}</span><h1>${copy(en(`Welcome, ${p.identity.kind==="guest"?t("shell","guestName"):p.identity.displayName}.`,`مرحباً، ${p.identity.kind==="guest"?t("shell","guestName"):p.identity.displayName}.`))}</h1><p>${copy(en("Complete the ten-question demo to collect an illustrative direction, skills to practise, and a personal next step in this browser.","أكمل التجربة ذات الأسئلة العشرة لتحصل على اتجاه توضيحي ومهارات للتدرب وخطوة شخصية تالية في هذا المتصفح."))}</p><a class="button" href="#assessment">${t("home","begin")} <span class="dir-arrow">→</span></a></section></div></div>`;const c=lead(j),tasks=roadmap(c).flatMap(x=>x[2]),next=tasks.find(x=>!j.roadmap.includes(x[0]));return `<div class="view"><div class="shell"><section class="dashboard-hero reveal"><div class="dashboard-copy"><span class="eyebrow" style="color:#ccebc6">${t("shell","dashboard")}</span><h1>${copy(en(`Welcome back, ${p.identity.kind==="guest"?t("shell","guestName"):p.identity.displayName}`,`مرحباً بعودتك، ${p.identity.kind==="guest"?t("shell","guestName"):p.identity.displayName}`))}</h1><p>${copy(en(`Your saved demo journey points to `,`تشير رحلتك التوضيحية المحفوظة إلى `))}<strong>${copy(c.name)}</strong>. ${copy(en("Keep using the information as a prompt for small experiments and conversations.","استمر في استخدام المعلومات كمحفز لتجارب ومحادثات صغيرة."))}</p><a class="button button-outline" style="border-color:#cfe6cf;color:#fff" href="#profile">${t("common","profile")} <span class="dir-arrow">→</span></a></div><div class="dashboard-media">${media("workplace",en("Saudi professionals collaborating in an office","محترفون سعوديون يتعاونون في مكتب"))}</div></section><section class="dashboard-grid"><article class="dashboard-card reveal"><h2>${copy(en("Leading path","المسار الأبرز"))}</h2><strong>${copy(c.name)}</strong><p>${t("common","match",{score:n(c.score)})}</p><a class="button button-outline" href="#compare">${copy(en("Compare paths","قارن المسارات"))}</a></article><article class="dashboard-card reveal"><h2>${copy(en("Roadmap progress","تقدم خارطة الطريق"))}</h2><strong>${n(j.roadmap.length)}/${n(tasks.length)} ${copy(en("steps","خطوات"))}</strong><p>${copy(j.roadmap.length?en("You are turning a direction into evidence.","أنت تحوّل الاتجاه إلى دليل."):en("Mark one small action to begin.","حدد إجراءً صغيراً للبدء."))}</p><a class="button button-outline" href="#roadmap">${copy(en("Open roadmap","افتح خارطة الطريق"))}</a></article><article class="dashboard-card reveal"><h2>${t("common","next")}</h2><strong style="font-size:17px">${next?copy(next[1]):copy(en("Choose a new project","اختر مشروعاً جديداً"))}</strong><p>${next?copy(en("A small learning action is waiting for you.","ينتظرك إجراء تعلم صغير.")):copy(en("You completed this demo plan.","لقد أكملت هذه الخطة التوضيحية."))}</p><a class="button button-outline" href="#skills">${copy(en("Review skill focus","راجع تركيز المهارات"))}</a></article></section></div></div>`;}
function render(){analysisTimers.forEach(clearTimeout);analysisTimers=[];applyPreferences();renderShell();const r=route(),views={home:renderHome,assessment:renderAssessment,analysis:()=>renderAnalysis(0),results:renderResults,advanced:renderAdvanced,profile:renderProfile,skills:renderSkills,roadmap:renderRoadmap,compare:renderCompare,dashboard:renderDashboard};if(!views[r]){go("#home");return;}app.innerHTML=views[r]();document.querySelectorAll("[data-nav]").forEach(a=>a.toggleAttribute("aria-current",a.dataset.nav===r));closeMenus();setupReveals();requestAnimationFrame(()=>{const h=app.querySelector("h1[tabindex],h1,h2[tabindex]");if(h){h.setAttribute("tabindex","-1");h.focus({preventScroll:true});}});if(r==="analysis")startAnalysis();}
function setupReveals(){if(matchMedia("(prefers-reduced-motion: reduce)").matches)return;const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("visible");o.unobserve(e.target);}}),{threshold:.12});app.querySelectorAll(".reveal").forEach(e=>o.observe(e));}
function startAnalysis(){[650,1350,2050].forEach((time,i)=>analysisTimers.push(setTimeout(()=>{if(route()!=="analysis")return;app.innerHTML=renderAnalysis(i);if(i===2)analysisTimers.push(setTimeout(()=>{if(route()==="analysis")go("#results");},620));},matchMedia("(prefers-reduced-motion: reduce)").matches?20:time)));}
function closeMenu(name,{restoreFocus=false}={}){const config={mobile:["#mobile-menu",".menu-toggle"],more:["#more-menu",".nav-more"],profile:["#profile-menu","[data-profile-menu]"]}[name];if(!config)return;const [menu,trigger]=config,element=document.querySelector(menu),control=document.querySelector(trigger),wasOpen=element&&!element.hidden;element?.setAttribute("hidden","");control?.setAttribute("aria-expanded","false");if(restoreFocus&&wasOpen)menuTriggers[name]?.focus?.();menuTriggers[name]=null;}
function closeMenus(options={}){closeMenu("mobile",options);closeMenu("more",options);closeMenu("profile",options);}
function openProfile(trigger){closeMenus();dialogTriggers.profile=trigger||document.activeElement;const d=document.querySelector("#profile-dialog");d?.showModal();setTimeout(()=>d?.querySelector("#profile-name")?.focus(),0);}
function closeProfile({restoreFocus=true}={}){const d=document.querySelector("#profile-dialog");if(d?.open)d.close();if(restoreFocus)dialogTriggers.profile?.focus?.();dialogTriggers.profile=null;}
function openReset(trigger){closeMenus();dialogTriggers.reset=trigger||document.activeElement;const d=document.querySelector("#reset-dialog");d?.showModal();setTimeout(()=>d?.querySelector("[data-close-reset]")?.focus(),0);}
function closeReset({restoreFocus=true}={}){const d=document.querySelector("#reset-dialog");if(d?.open)d.close();if(restoreFocus)dialogTriggers.reset?.focus?.();dialogTriggers.reset=null;}
function activateGuest(){if(!state.profiles.guest)state.profiles.guest={identity:{displayName:"Guest",email:"",kind:"guest"},journey:freshJourney()};state.session.activeProfileId="guest";save();announce(copy(en("Guest demo profile is ready.","الملف التجريبي للضيف جاهز.")));render();}
function activateProfile(id){if(!state.profiles[id])return;state.session.activeProfileId=id;save();closeProfile();announce(copy(en("Local demo profile resumed.","تمت متابعة الملف التجريبي المحلي.")));render();}
function completeAdvanced(){const j=journey();if(!j)return;j.advanced.complete=true;j.advanced.index=4;updateResult(j);save();announce(copy(en("Preferences saved. Your illustrative profile has been updated.","تم حفظ التفضيلات وتحديث ملفك التوضيحي.")));go("#results");}
function currentTask(){return document.activeElement;}
document.addEventListener("click",e=>{const x=e.target.closest("button,a,input");if(!x)return;if(x.matches("[data-language]")){state.preferences.locale=state.preferences.locale==="en"?"ar":"en";save();render();announce(t("shell","langChanged"));return;}if(x.matches("[data-theme-toggle]")){state.preferences.theme=state.preferences.theme==="light"?"dark":"light";save();render();announce(t("shell","themeChanged"));return;}if(x.matches("[data-open-profile]")){e.preventDefault();openProfile(x);return;}if(x.matches("[data-close-profile]")){closeProfile();return;}if(x.matches("[data-guest]")){activateGuest();return;}if(x.matches("[data-resume-profile]")){activateProfile(x.dataset.resumeProfile);return;}if(x.matches("[data-profile-menu]")){const m=document.querySelector("#profile-menu"),open=m.hidden;if(open){closeMenu("more");menuTriggers.profile=x;m.hidden=false;x.setAttribute("aria-expanded","true");setTimeout(()=>m.querySelector("button")?.focus(),0);}else closeMenu("profile",{restoreFocus:true});return;}if(x.matches("[data-sign-out]")){state.session.activeProfileId=null;save();announce(copy(en("You have signed out of this local demo profile.","تم تسجيل خروجك من هذا الملف التجريبي المحلي.")));render();return;}if(x.matches("[data-open-reset]")){openReset(x);return;}if(x.matches("[data-close-reset]")){closeReset();return;}if(x.matches("[data-confirm-reset]")){const p=activeProfile();if(p){p.journey=freshJourney();save();closeReset({restoreFocus:false});announce(copy(en("This profile's demo data has been reset.","تمت إعادة ضبط بيانات تجربة هذا الملف.")));go("#dashboard");}return;}if(x.matches("[data-answer]")){const j=journey();if(!j){openProfile(x);return;}const a=Number(x.dataset.answer),q=j.assessment.index;j.assessment.answers[q]=a;updateResult(j);save();x.classList.add("is-selected");x.setAttribute("aria-pressed","true");announce(copy(en(`Answer selected for question ${q+1}.`,`تم اختيار إجابة للسؤال ${n(q+1)}.`)));setTimeout(()=>{if(route()!=="assessment")return;if(q>=9){j.assessment.complete=true;j.assessment.index=9;updateResult(j);save();go("#analysis");}else{j.assessment.index=q+1;save();render();}},matchMedia("(prefers-reduced-motion: reduce)").matches?0:280);return;}if(x.matches("[data-assessment-back]")){const j=journey();j.assessment.index=Math.max(0,j.assessment.index-1);save();render();return;}if(x.matches("[data-skip-analysis]")){go("#results");return;}if(x.matches("[data-advanced-choice]")){const j=journey(),key=ADVANCED[j.advanced.index][0];j.advanced.data[key]=x.dataset.advancedChoice;updateResult(j);save();render();return;}if(x.matches("[data-skill-chip]")){const j=journey(),id=x.dataset.skillChip;j.advanced.data.skills=j.advanced.data.skills.includes(id)?j.advanced.data.skills.filter(v=>v!==id):[...j.advanced.data.skills,id];updateResult(j);save();render();return;}if(x.matches("[data-advanced-back]")){const j=journey();j.advanced.index=Math.max(0,j.advanced.index-1);save();render();return;}if(x.matches("[data-advanced-next]")){const j=journey();if(j.advanced.index===4)completeAdvanced();else{j.advanced.index++;save();render();}return;}if(x.matches("[data-task]")){const j=journey(),id=x.dataset.task;j.roadmap=x.checked?[...new Set([...j.roadmap,id])]:j.roadmap.filter(v=>v!==id);save();announce(copy(x.checked?en("Roadmap action completed.","تم إكمال إجراء خارطة الطريق."):en("Roadmap action marked incomplete.","تم وضع إجراء خارطة الطريق كغير مكتمل.")));render();return;}if(x.matches("[data-career]")){const j=journey();if(j){j.selectedCareer=x.dataset.career;save();}}if(x.matches(".menu-toggle")){const m=document.querySelector("#mobile-menu"),open=m.hidden;if(open){closeMenu("more");closeMenu("profile");menuTriggers.mobile=x;m.hidden=false;x.setAttribute("aria-expanded","true");x.setAttribute("aria-label",t("shell","closeNav"));}else{closeMenu("mobile",{restoreFocus:true});x.setAttribute("aria-label",t("shell","openNav"));}return;}if(x.matches(".nav-more")){const m=document.querySelector("#more-menu"),open=m.hidden;if(open){closeMenu("profile");menuTriggers.more=x;m.hidden=false;x.setAttribute("aria-expanded","true");setTimeout(()=>m.querySelector("a")?.focus(),0);}else closeMenu("more",{restoreFocus:true});return;}});
document.addEventListener("submit",e=>{if(e.target.id!=="profile-form")return;e.preventDefault();const form=e.target,name=form.name.value.trim(),email=form.email.value.trim(),err=form.querySelector("#profile-error");if(!name){err.textContent=t("shell","nameError");err.hidden=false;form.name.focus();return;}if(email&&!/^\S+@\S+\.\S+$/.test(email)){err.textContent=t("shell","emailError");err.hidden=false;form.email.focus();return;}const existing=Object.entries(state.profiles).find(([,p])=>p.identity.kind==="local"&&email&&p.identity.email.toLowerCase()===email.toLowerCase());const id=existing?.[0]||`local-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;if(!existing)state.profiles[id]={identity:{displayName:name,email,kind:"local"},journey:freshJourney()};state.session.activeProfileId=id;save();activateProfile(id);});
document.addEventListener("change",e=>{if(e.target.matches("[data-compare]")){const j=journey(),slot=e.target.dataset.compare==="first"?0:1;j.compare[slot]=e.target.value;save();render();}});
document.addEventListener("click",e=>{if(e.target.closest(".site-header"))return;closeMenus();});
document.addEventListener("keydown",e=>{if(e.key!=="Escape")return;const profile=document.querySelector("#profile-dialog"),reset=document.querySelector("#reset-dialog");if(profile?.open){e.preventDefault();closeProfile();return;}if(reset?.open){e.preventDefault();closeReset();return;}closeMenus({restoreFocus:true});});
document.addEventListener("close",e=>{if(e.target.id==="profile-dialog"){if(dialogTriggers.profile){dialogTriggers.profile.focus?.();dialogTriggers.profile=null;}}if(e.target.id==="reset-dialog"){if(dialogTriggers.reset){dialogTriggers.reset.focus?.();dialogTriggers.reset=null;}}},true);
document.addEventListener("cancel",e=>{if(e.target.id==="profile-dialog"||e.target.id==="reset-dialog"){e.preventDefault();e.target.id==="profile-dialog"?closeProfile():closeReset();}},true);
window.addEventListener("hashchange",render);applyPreferences();if(!location.hash)go("#home");else render();
